using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Services;namespace RaceDay.Mvc.Controllers;public class ParticipantController(RaceApi api):Controller{bool Allowed()=>HttpContext.Session.GetString("role")=="Participant";public async Task<IActionResult> MyEvents(){if(!Allowed())return Forbid();return View(await api.Get<List<Enrolment>>("api/enrolments/me")??new());}[HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Cancel(int id){if(!Allowed())return Forbid();var r=await api.Send(HttpMethod.Delete,$"api/enrolments/{id}");TempData["Notice"]=r.ok?"Your event entry has been cancelled.":r.error;return RedirectToAction(nameof(MyEvents));}public async Task<IActionResult> Results(){if(!Allowed())return Forbid();return View(await api.Get<List<RaceResult>>("api/results/me")??new());}public async Task<IActionResult> Profile(){if(!Allowed())return Forbid();return View(await api.Get<User>("api/users/me"));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> UpdateProfile(string firstName,string lastName,string email,string? phoneNumber){if(!Allowed())return Forbid();var r=await api.Send(HttpMethod.Put,"api/users/me",new{firstName,lastName,email,phoneNumber});TempData["Notice"]=r.ok?"Profile updated.":r.error;return RedirectToAction(nameof(Profile));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Picture(IFormFile file){if(!Allowed())return Forbid();var r=await api.Upload("api/files/profile-picture",file);TempData["Notice"]=r.ok?"Picture uploaded.":r.error;return RedirectToAction(nameof(Profile));}}